    ROUND((master_likuiditas_pilar1.pinjaman / master_likuiditas_pilar1.total_dpk)*100, 2) AS lik_p12i,
    ROUND((master_kredit_pilar1.kyd / master_likuiditas_pilar1.total_dpk)*100, 2) AS lik_p13,
    ROUND((master_likuiditas_pilar1.aset_likuid / master_likuiditas_pilar1.pendanaan_jangka_pendek)*100, 2) AS lik_p13a,
    ROUND(((master_likuiditas_pilar1.alat_likuid + master_likuiditas_pilar1.kredit_kolek_lancar) / master_likuiditas_pilar1.total_dpk)*100, 2) AS lik_p13b,
    ROUND((master_likuiditas_pilar1.deposito_6bln / master_likuiditas_pilar1.alat_likuid)*100, 2) AS lik_p13c,
    ROUND((((master_kredit_pilar1.kyd-master_likuiditas_pilar1.kredit_des_thn_sebelum)/master_likuiditas_pilar1.kredit_des_thn_sebelum) * 100) / 
        (((master_likuiditas_pilar1.total_dpk-master_likuiditas_pilar1.dpk_des_thn_sebelum)/master_likuiditas_pilar1.dpk_des_thn_sebelum) * 100)*100, 2) AS lik_p13d,
    ROUND((master_likuiditas_pilar1.deposan_tabungan_terbesar25 / master_likuiditas_pilar1.total_dpk)*100, 2) AS lik_p14,
    ROUND((master_likuiditas_pilar1.pendanaan_non_inti / master_likuiditas_pilar1.total_dpk)*100, 2) AS lik_p15,
    ROUND((master_likuiditas_pilar1.pendanaan_non_inti - master_likuiditas_pilar1.alat_likuid) / 
        (master_likuiditas_pilar1.total_aset - master_likuiditas_pilar1.aset_likuid), 2) AS lik_p15a,
    ROUND((master_likuiditas_pilar1.deposito_rs / master_likuiditas_pilar1.alat_likuid)*100, 2) AS lik_p15b,
    ROUND((master_likuiditas_pilar1.aset_likuid / master_likuiditas_pilar1.pendanaan_non_inti)*100, 2) AS lik_p15c,
    ROUND((master_likuiditas_pilar1.deposito_inti / master_likuiditas_pilar1.total_dpk)*100, 2) AS lik_p15d


FROM frame_laporan_profil_risiko 
INNER JOIN master_kredit_pilar1 ON frame_laporan_profil_risiko.id_profil_risiko = master_kredit_pilar1.id_profil_risiko
INNER JOIN master_kredit_pilar2 ON frame_laporan_profil_risiko.id_profil_risiko = master_kredit_pilar2.id_profil_risiko
INNER JOIN master_kredit_pilar3 ON frame_laporan_profil_risiko.id_profil_risiko = master_kredit_pilar3.id_profil_risiko

INNER JOIN master_likuiditas_pilar1 ON frame_laporan_profil_risiko.id_profil_risiko = master_likuiditas_pilar1.id_profil_risiko
    WHERE (tahun * 10 + periode) BETWEEN $start_key AND $end_key 
        AND kantor_cabang = $kantor_cabang AND user = $user
    ORDER BY tahun ASC, periode ASC
";


