                                                <th>Risiko Inheren</th>
                                                <?php foreach ($inheren as $val): ?>
                                                    <td><?= $val ?></td>
                                                <?php endforeach; ?>
                                                <th>
                                                        <center><b>
                                                        <?php
                                                        // Koneksi database
                                                        error_reporting(0);
                                                        ini_set('display_errors', 0);


                                                      

                                                        // Ambil data tingkat_risiko dalam rentang waktu
                                                        $query = "
                                                            SELECT (tahun * 10 + periode) AS key_form, inheren_kredit
                                                            FROM frame_laporan_profil_risiko 
                                                            INNER JOIN keterangan_profil_kredit 
                                                                ON frame_laporan_profil_risiko.id_profil_risiko = keterangan_profil_kredit.id_profil_risiko
                                                            WHERE (tahun * 10 + periode) BETWEEN $start_key AND $end_key 
                                                                AND kantor_cabang = $kantor_cabang AND user = $user
                                                            ORDER BY tahun ASC, periode ASC
                                                        ";

                                                        $result = mysqli_query($conn, $query);

                                                        $x = [];
                                                        $y = [];
                                                        $i = 0;

                                                        while ($row = mysqli_fetch_assoc($result)) {
                                                            if (is_numeric($row['inheren_kredit'])) {
                                                                $x[] = $i++; // Gunakan indeks sebagai variabel waktu (bisa diganti key_form)
                                                                $y[] = floatval($row['inheren_kredit']);
                                                            }
                                                        }

                                                        // Cek jumlah data
                                                        $n = count($x);
                                                        if ($n < 2) {
                                                            $peringatan = "Data tidak cukup untuk analisis tren atau pilih range periode lagi.";
                                                        }
                                                        else {
                                                            $peringatan = " ";
                                                        }

                                                        // Hitung regresi linier (y = a + b*x)
                                                        $sumX = array_sum($x);
                                                        $sumY = array_sum($y);
                                                        $sumXY = 0;
                                                        $sumX2 = 0;

                                                        for ($i = 0; $i < $n; $i++) {
                                                            $sumXY += $x[$i] * $y[$i];
                                                            $sumX2 += $x[$i] * $x[$i];
                                                        }

                                                        $b = number_format(($n * $sumXY - $sumX * $sumY) / ($n * $sumX2 - $sumX * $sumX),2); // slope
                                                        $a = ($sumY - $b * $sumX) / $n; // intercept

                                                        // Tentukan tren
                                                        if ($b > 0.01) {
                                                            $tren = "Memburuk";
                                                        } elseif ($b < -0.01) {
                                                            $tren = "Membaik";
                                                        } elseif($b == 0) {
                                                            $tren = "Stay";
                                                        }
 
                                                        if ($tren == "Membaik") {
                                                            echo '<span class="badge badge-success-lighten rounded-pill">Tren Membaik</span> <i class="mdi mdi-arrow-down text-success"></i><br>' . $b . '';
                                                        } else if ($tren == "Memburuk") {
                                                            echo '<span class="badge badge-danger-lighten rounded-pill">Tren Memburuk</span> <i class="mdi mdi-arrow-up text-danger"></i><br>' . $b . '';
                                                        } else if ($tren == "Stay") {
                                                            echo '<span class="badge badge-warning-lighten rounded-pill">Tren Stabil</span> <i class="mdi mdi-arrow-right text-warning"></i><br>' . $b . '';
                                                        } else {
                                                            echo '<span>-</span> </i>';
                                                        }
                                                        
                                                        
                                                        ?></b></center>
                                                </th>
                                            </tr>
