<script>
document.addEventListener('DOMContentLoaded', function () {
    var tabLinks = document.querySelectorAll('a[href="#dashboard-profil-nilai"], a[href="#dashboard-profil-peringkat"]');
    var tabPanes = document.querySelectorAll('#dashboard-profil-nilai, #dashboard-profil-peringkat');

    function activateDashboardProfilTab(target) {
        tabLinks.forEach(function (link) {
            var active = link.getAttribute('href') === target;
            link.classList.toggle('active', active);
            link.setAttribute('aria-expanded', active ? 'true' : 'false');
        });
        tabPanes.forEach(function (pane) {
            var active = '#' + pane.id === target;
            pane.classList.toggle('active', active);
            pane.classList.toggle('show', active);
        });
    }

    tabLinks.forEach(function (link) {
        link.addEventListener('click', function () {
            activateDashboardProfilTab(this.getAttribute('href'));
        });
        link.addEventListener('shown.bs.tab', function () {
            activateDashboardProfilTab(this.getAttribute('href'));
        });
    });

    activateDashboardProfilTab('#dashboard-profil-nilai');
});
</script>

